class TestFallbackBehavior:
    """Tests for fallback behavior across availability permutations."""

    @pytest.mark.parametrize(
        "docker_available,docker_healthy,podman_available,podman_healthy,expected",
        [
            # (docker_bin, docker_health, podman_bin, podman_health, expected_runtime)
            (True, True, True, True, "docker"),
            (True, True, True, False, "docker"),
            (True, True, False, False, "docker"),
            (True, False, True, True, "podman"),
            (True, False, True, False, "none"),
            (True, False, False, False, "none"),
            (False, False, True, True, "podman"),
            (False, False, True, False, "none"),
            (False, False, False, False, "none"),
        ],
    )
    def test_all_permutations(
        self,
        factory,
        mock_docker_class,
        mock_podman_class,
        mock_which,
        docker_available,
        docker_healthy,
        podman_available,
        podman_healthy,
        expected,
    ):
        """Verify runtime selection across all Docker/Podman availability permutations."""
        docker_path = "/usr/bin/docker" if docker_available else None
        podman_path = "/usr/bin/podman" if podman_available else None
        _set_which(mock_which, docker_path, podman_path)

        docker_cls, docker_instance = mock_docker_class
        podman_cls, podman_instance = mock_podman_class

        if docker_available:
            _set_health(docker_instance, docker_healthy)
        if podman_available:
            _set_health(podman_instance, podman_healthy)

        if expected == "none":
            with pytest.raises(RuntimeNotFoundError):
                factory.create()
        else:
            runtime = factory.create()
            if expected == "docker":
                assert runtime == docker_instance
                docker_cls.assert_called_once()
                podman_cls.assert_not_called()
            else:
                assert runtime == podman_instance
                docker_cls.assert_called_once()
                podman_cls.assert_called_once()


